local plain = unseal("[=[" .. D .. "]=]")
if not plain then error("Squad Manager: this file is damaged. Please install the plugin again.") end
local me
pcall(function() me = debug.getinfo(1, "S").source end)
if type(me) == "string" then me = (me:gsub("^[@=]", "")) else me = nil end
local fn, err
if _VERSION == "Lua 5.1" and setfenv then
    fn, err = loadstring(plain, "=Cricket")
    if fn then setfenv(fn, getfenv(1)) end
else
    fn, err = load(plain, "=Cricket", "t", _ENV)
end
if not fn then error("Squad Manager could not start: " .. tostring(err)) end
fn(unseal, me)
